// 段階6: 新しい検査結果のときだけ後段へ進める(Scheduleの毎日実行で同じ結果を繰り返し通知しないため)
// 記録の書き込みはここでは行わない。パイプライン全体が成功した最後のノードで行う(途中失敗時に再試行できるように)
const data = $input.first().json;
const staticData = $getWorkflowStaticData('global');

const isTest = $execution.mode === 'test';
const isNew = isTest || staticData.lastNotifiedDate !== data.exam_date;

return [{
    json: { ...data, is_new: isNew, last_notified: staticData.lastNotifiedDate ?? null },
}];

// 段階6: 記録の書き込みをここに移す。パイプライン全体(所見生成・保存)が成功して初めて
// 「通知済み」とみなす(途中で失敗したら、次回また同じ検査結果を拾い直せるように)
const staticData = $getWorkflowStaticData('global');
const isTest = $execution.mode === 'test';
const examDate = $('新着判定').first().json.exam_date;

if (!isTest) {
    staticData.lastNotifiedDate = examDate;
}

return $input.all();

// 段階7: 通知対象の絞り込み。慢性/急性を問わずすべての範囲外項目を対象にする。
// 「慢性的に基準値外」フラグ(trend_graph.pyが履歴から機械的に算出)は除外理由にせず、
// 観測事実の注記としてのみ使う(疾患名や患者像を仮定した理由付けはしない)。
// 慢性項目は「いつも同じ話」で埋もれやすいため、MAX_ITEMSの枠内で必ず確保する
const data = $input.first().json;
const summary = data.summary ?? [];

const MAX_ITEMS = 8;

const latestDate = summary.reduce((a, s) => (s["検査日"] > a ? s["検査日"] : a), "");

function parseTarget(raw) {
    if (!raw) return [null, null];
    let m = /^([\d.]+)~([\d.]+)$/.exec(raw);
    if (m) return [Number(m[1]), Number(m[2])];
    m = /^([\d.]+)以下$/.exec(raw);
    if (m) return [null, Number(m[1])];
    m = /^([\d.]+)以上$/.exec(raw);
    if (m) return [Number(m[1]), null];
    return [null, null];
}

function deviation(s) {
    const [low, high] = parseTarget(s["目標値"]);
    const v = s["検査結果"];
    if (low !== null && high !== null) {
          const width = high - low;
          return width > 0 ? (v > high ? v - high : low - v) / width : 0;
    }
    if (high !== null) return (v - high) / high;
    if (low !== null) return (low - v) / low;
    return 0;
}

const scored = summary
  .filter((s) => s["判定"] !== "範囲内")
  .map((s) => {
        const stale = s["検査日"] !== latestDate;
        const worsening =
                (s["判定"] === "目標範囲より高い" && s["前回との比較"] === "上昇") ||
                (s["判定"] === "目標範囲より低い" && s["前回との比較"] === "低下");
        const item = { ...s, _score: deviation(s) * (worsening ? 1.5 : 1) * (stale ? 0.5 : 1) };
        const notes = [];
        if (item["注記"]) notes.push(item["注記"]);
        if (s["慢性的に基準値外"]) notes.push("記録のある全期間で目標範囲外");
        if (stale) notes.push(`この値は${s["検査日"]}のもので、最新の${latestDate}では測定されていない`);
        if (notes.length) item["注記"] = notes.join(" / ");
        return item;
  })
  .sort((a, b) => b._score - a._score);

// 慢性項目は枠に関わらず必ず含め、残りの枠を急性項目で埋める
const chronic = scored.filter((s) => s["慢性的に基準値外"]);
const acute = scored.filter((s) => !s["慢性的に基準値外"]);
const acuteBudget = Math.max(0, MAX_ITEMS - chronic.length);
const picked = [...chronic, ...acute.slice(0, acuteBudget)]
  .sort((a, b) => b._score - a._score)
  .map(({ _score, ...rest }) => rest);

return [{
    json: {
          summary: picked,
          exam_date: latestDate,
          total_count: summary.length,
          out_of_range_count: scored.length,
          others: acute.slice(acuteBudget).map((s) => s["項目名"]),
    },
}];

const data = $input.first().json;

const lines = data.summary.map((s) => {
    const full = s["正式名称"] ? `(${s["正式名称"]})` : "";
    const target = s["目標値"] || "設定なし";
    const kind = s["目標値の種別"] || "";
    let line = `${s["項目名"]}${full}: ${s["検査結果"]} (目標値 ${target}[${kind}], ${s["判定"]}`;
    if (s["前回との比較"]) {
          line += `, 前回より${s["前回との比較"]}`;
    }
    line += ")";
    if (s["注記"]) {
          line += ` ※${s["注記"]}`;
    }
    return line;
});

const summary_text = lines.join("\n");

const prompt = `以下は検査結果の要約です。各項目について、目標値との比較と前回からの変化を踏まえ、
本人にも分かる言葉で短くコメントしてください。

## 書き方
- 複数の項目をまとめて1つのコメントにしてはならない。必ず1項目ずつ書く
- 項目名は入力に書かれたものをそのまま使う。別名に言い換えてはならない
- 判定と矛盾する評価を併記してはならない。「基準より高いが正常範囲内」のような
  書き方は禁止。判定が「目標範囲より高い」なら、範囲内とは書かない
  - 項目名の後の括弧内が正式名称。略号の項目は初出時に一度だけこれを添える
  - 括弧が無い項目に、正式名称を推測して付けてはならない
  - 各項目の判定(「範囲内」「目標範囲より高い」「目標範囲より低い」)は、その語を
    そのままコメントに含める。言い換えたり向きを変えたりしてはならない
    - 「注記」に情報があれば、その内容を踏まえてコメントする。注記に無い理由を推測で
      補ってはならない(特定の疾患や患者像を仮定した説明もしない)
      - 各項目1〜2文
      - 検査値が示す「状態」の説明にとどめ、薬剤名を挙げた治療の提案はしない
      - 数値の羅列ではなく、目標範囲との関係と前回からの向きを伝える

      ## 重要
      - これは医療アドバイスではありません
      - 目標値は一般的な目安であり、個別の判断は専門家に委ねてください
      - 文末に「診断・治療方針は必ず主治医にご確認ください」と明記してください

      ## 検査結果
      ${summary_text}`;

return [{ json: { summary_text, prompt } }];

const text = $input.first().json.content ?? "";

// LLMが使いがちな表記を、患者向けの正しい呼称に統一する
const TERM_MAP = {
  "パラチホモイドホルモン": "副甲状腺ホルモン",
  "パラチホイドホルモン": "副甲状腺ホルモン",
  "パラサイロイドホルモン": "副甲状腺ホルモン",
  "パラトルモン": "副甲状腺ホルモン",
  "上皮小体ホルモン": "副甲状腺ホルモン",
};

// 思考型モデルに差し替えたときのために除去処理は残す
let comment = text.replace(/<think>[\s\S]*?<\/think>/g, "").trim();
for (const [wrong, right] of Object.entries(TERM_MAP)) {
  comment = comment.replaceAll(wrong, right);
}

// 「診断・治療方針は…」をLLMが項目ごとに繰り返すことがあるため、
// コード側で一旦すべて除去し、文末に1回だけ付け直す
const DISCLAIMER = "診断・治療方針は必ず主治医にご確認ください。";
// 生成が正常なら、指示どおりLLMは必ず免責文を含めるはず。無ければ途中で
// 打ち切られた可能性が高いため、ここでエラーにしてPDF送信まで進めない
// (ネイティブAIノードはdone:falseを検知できないため、この判定で代替する)
if (!comment.includes(DISCLAIMER)) {
  throw new Error(`免責文が見つかりません。出力が途中で切れた可能性があります。末尾: ...${comment.slice(-200)}`);
}

comment = comment.split(DISCLAIMER).join("").replace(/\n{3,}/g, "\n\n").trim();
comment += `\n\n${DISCLAIMER}`;

const markdown = `![検査結果推移](http://localhost:8000/trend_n8n_image)\n\n${comment}`;

return [{ json: { comment, markdown } }];

const content = $input.first().json.content ?? "";
const withoutThink = content.replace(/<think>[\s\S]*?<\/think>/g, "").trim();
const DISCLAIMER = "診断・治療方針は必ず主治医にご確認ください。";
const hasDisclaimer = withoutThink.includes(DISCLAIMER);

// $runIndexはこのノード自体の実行回数(0始まり)。ループでOllamaに戻すたびに増える
const MAX_ATTEMPTS = 3;
const isLastAttempt = $runIndex >= MAX_ATTEMPTS - 1;

return [{
  json: {
    content,
    ok: hasDisclaimer,
    giveUp: !hasDisclaimer && isLastAttempt,
    prompt: $('AIパラメータ生成').first().json.prompt,
  },
}];
